-- درباره ما  (/fa/about)
INSERT INTO Pages (Id, Title, Slug, Status, MetaTitle, MetaDescription, Culture, LocalizationGroupId, CreatedAt, UpdatedAt, PublishedAt)
VALUES (@AboutId, N'درباره ما', N'about', 'Published', N'درباره ما | نیک نگاه', N'نیک نگاه، چاپخانه‌ی دیجیتال: دقت در رنگ، خوش‌قولی در تحویل و مشاوره در انتخابِ کاغذ و پوشش.', 'fa', NULL, SYSUTCDATETIME(), SYSUTCDATETIME(), SYSUTCDATETIME());
INSERT INTO PageBlocks (Id, PageId, BlockType, SortOrder, Data, Styles) VALUES
    (NEWID(), @AboutId, N'Hero', 0,
     N'{"layout":"split","eyebrow":"درباره‌ی نیک نگاه","title":"هر چاپ،\nبا یک نگاهِ دقیق","subtitle":"نیک نگاه چاپخانه‌ای دیجیتال است برای کسب‌وکارها و آدم‌هایی که می‌خواهند کارشان روی کاغذ همان‌طور دیده شود که روی صفحه طراحی کرده‌اند.","imageUrl":"/uploads/nicnegah-logo.png"}',
     N'{"backgroundColor":"transparent","paddingTop":"0","paddingBottom":"0","paddingLeft":"0","paddingRight":"0"}'),
    (NEWID(), @AboutId, N'RichText', 1,
     N'{"content":"<p>اسمِ ما از همین‌جا آمده: نگاهِ نیک. پیش از چاپ، فایل را نگاه می‌کنیم؛ رنگ، وضوح و حاشیه‌ی برش را. اگر چیزی درست نیست، پیش از آن‌که کاغذ و وقتِ شما هدر برود، خبرتان می‌کنیم. بعد نمونه‌ی رنگ را می‌بینید و تا تأیید نکنید، چاپِ نهایی شروع نمی‌شود.</p>"}',
     N'{"backgroundColor":"transparent","paddingTop":"0","paddingBottom":"0","paddingLeft":"0","paddingRight":"0","textAlign":"center","fontSize":"1.125rem"}'),
    (NEWID(), @AboutId, N'Stats', 2,
     N'{"backgroundColor":"#0E252D","stats":[{"value":"[۱۲]+","label":"سال تجربه"},{"value":"[۴۸] ساعت","label":"میانگینِ زمانِ تحویل"},{"value":"[۳۰۰۰]+","label":"سفارشِ چاپ‌شده"},{"value":"۶","label":"گروهِ خدمات"}]}',
     N'{"backgroundColor":"transparent","paddingTop":"0","paddingBottom":"0","paddingLeft":"0","paddingRight":"0"}'),
    (NEWID(), @AboutId, N'FeaturesList', 3,
     N'{"sectionTitle":"آنچه برایمان مهم است","columns":3,"features":[{"icon":"shield","title":"دقت در رنگ","description":"کالیبره‌کردنِ دستگاه‌ها و نمونه‌ی رنگ پیش از هر چاپ."},{"icon":"clock","title":"خوش‌قولی","description":"زمانِ تحویل را از اول می‌گوییم و به آن پایبندیم."},{"icon":"message-circle","title":"مشاوره‌ی صادقانه","description":"کاغذ و پوششی را پیشنهاد می‌دهیم که به کارِ شما بیاید، نه گران‌ترین را."}]}',
     N'{"backgroundColor":"transparent","paddingTop":"0","paddingBottom":"0","paddingLeft":"0","paddingRight":"0"}'),
    (NEWID(), @AboutId, N'Timeline', 4,
     N'{"sectionTitle":"مسیرِ ما","events":[{"date":"[۱۳۹۲]","title":"شروع با یک دستگاه","description":"چاپِ کارت ویزیت و تراکت برای کسب‌وکارهای محله."},{"date":"[۱۳۹۷]","title":"چاپِ عریض","description":"اضافه‌شدنِ بنر، رول‌آپ و چاپِ نمایشگاهی."},{"date":"[۱۴۰۲]","title":"لیبل و بسته‌بندی","description":"برشِ دیجیتال برای لیبل، استیکر و جعبه‌ی تیراژِ کم."},{"date":"[۱۴۰۵]","title":"سفارشِ آنلاین","description":"ارسالِ فایل و استعلامِ قیمت از راهِ دور."}]}',
     N'{"backgroundColor":"#0E252D","paddingTop":"0","paddingBottom":"0","paddingLeft":"0","paddingRight":"0"}'),
    (NEWID(), @AboutId, N'CallToAction', 5,
     N'{"title":"کارِ بعدی‌تان را با ما چاپ کنید","description":"فایل یا ایده‌تان را بفرستید؛ قیمت و زمانِ تحویل را همان روز اعلام می‌کنیم.","buttonText":"استعلام قیمت","buttonLink":"/fa/contact"}',
     N'{"backgroundColor":"transparent","paddingTop":"0","paddingBottom":"0","paddingLeft":"0","paddingRight":"0"}');

-- تماس با ما  (/fa/contact)
INSERT INTO Pages (Id, Title, Slug, Status, MetaTitle, MetaDescription, Culture, LocalizationGroupId, CreatedAt, UpdatedAt, PublishedAt)
VALUES (@ContactId, N'تماس با ما', N'contact', 'Published', N'تماس با ما | نیک نگاه', N'نشانی، ساعتِ کار و راه‌های تماس با نیک نگاه؛ برای استعلامِ قیمت و ارسالِ فایل.', 'fa', NULL, SYSUTCDATETIME(), SYSUTCDATETIME(), SYSUTCDATETIME());
INSERT INTO PageBlocks (Id, PageId, BlockType, SortOrder, Data, Styles) VALUES
    (NEWID(), @ContactId, N'Heading', 0,
     N'{"text":"تماس با ما","subtitle":"برای استعلامِ قیمت، نوعِ کار، تیراژ و اندازه را بنویسید. فایل را می‌توانید با ایمیل یا تلگرام بفرستید.","level":"h1","alignment":"center"}',
     N'{"backgroundColor":"#0E252D","paddingTop":"2rem","paddingBottom":"2rem","paddingLeft":"0","paddingRight":"0","borderColor":"#16323B","borderWidth":"0 0 1px 0"}'),
    (NEWID(), @ContactId, N'Columns', 1,
     REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(N'{"columnCount":2,"gap":"2rem","columns":[{"width":"38%","blocks":[{"blockType":"CardGrid","data":"{\"columns\":1,\"layout\":\"inline\",\"cards\":[{\"icon\":\"map-pin\",\"title\":\"نشانی\",\"description\":\"{{N_ADDRESS}}\"},{\"icon\":\"clock\",\"title\":\"ساعتِ کار\",\"description\":\"{{N_HOURS}}\"},{\"icon\":\"phone\",\"title\":\"تلفن\",\"description\":\"{{N_PHONE}}\"},{\"icon\":\"mail\",\"title\":\"ارسالِ فایل با ایمیل\",\"description\":\"{{N_ORDER_EMAIL}}\"},{\"icon\":\"brand-telegram\",\"title\":\"تلگرام\",\"description\":\"{{N_TELEGRAM}}\"},{\"icon\":\"brand-instagram\",\"title\":\"اینستاگرام\",\"description\":\"{{N_INSTAGRAM}}\"}]}"}]},{"width":"60%","blocks":[{"blockType":"ContactForm","data":"{\"title\":\"استعلامِ قیمت\",\"description\":\"مشخصاتِ کار را بنویسید؛ در ساعتِ کاری پاسخ می‌دهیم.\",\"recipientEmail\":\"{{N_RECIPIENT_EMAIL}}\",\"submitButtonText\":\"ارسالِ درخواست\",\"fields\":[{\"label\":\"نام\",\"name\":\"name\",\"type\":\"text\",\"required\":true,\"placeholder\":\"نام یا نامِ شرکت\"},{\"label\":\"ایمیل\",\"name\":\"email\",\"type\":\"email\",\"required\":true,\"placeholder\":\"email@example.com\"},{\"label\":\"نوعِ کار\",\"name\":\"subject\",\"type\":\"text\",\"required\":false,\"placeholder\":\"مثلاً کارت ویزیت طلاکوب\"},{\"label\":\"توضیحات\",\"name\":\"message\",\"type\":\"textarea\",\"required\":true,\"placeholder\":\"تیراژ، اندازه، کاغذ، زمانِ موردنیاز و شماره‌ی تماس\"}]}"}]}]}', N'{{N_ADDRESS}}', @AddressJson2), N'{{N_HOURS}}', @HoursJson2), N'{{N_PHONE}}', @PhoneJson2), N'{{N_ORDER_EMAIL}}', @OrderEmailJson2), N'{{N_TELEGRAM}}', @TelegramJson2), N'{{N_INSTAGRAM}}', @InstagramJson2), N'{{N_RECIPIENT_EMAIL}}', @RecipientEmailJson2),
     N'{"backgroundColor":"transparent","paddingTop":"0","paddingBottom":"0","paddingLeft":"0","paddingRight":"0"}'),
    (NEWID(), @ContactId, N'MapEmbed', 2,
     REPLACE(N'{"embedUrl":"{{MAP_EMBED_URL}}","height":420}', N'{{MAP_EMBED_URL}}', @MapEmbedUrlJson),
     N'{"backgroundColor":"transparent","paddingTop":"0","paddingBottom":"3rem","paddingLeft":"0","paddingRight":"0"}');

COMMIT TRANSACTION;

SELECT p.Slug, p.Title, p.Status, COUNT(b.Id) AS Blocks
FROM Pages p LEFT JOIN PageBlocks b ON b.PageId = p.Id
WHERE p.Culture = 'fa' AND p.Slug IN (N'', N'services', N'about', N'contact')
GROUP BY p.Slug, p.Title, p.Status;
